//! `BillboardCollection` against a capture of the pinned CesiumJS engine on a
//! real WebGL2 context, `tests/data/scene-billboard-collection.json`
//! (generated by `tools/cesium/generate-scene-billboard-collection.mjs`).
//! Each scenario is replayed through a recording WebGL host and, after every
//! update, compared on the exact vertex bytes and buffer uploads, the draw
//! commands, the shader defines, the collection's bookkeeping and, after the
//! frame's `afterRender` atlas update, the atlas and every billboard's image
//! state. The `*Batched` scenarios run without instancing.

use base64::Engine;
use cesium_rs::core::*;
use cesium_rs::renderer::{Context, Gl, GlValue, UniformFrame, UniformFrustum};
use cesium_rs::scene::billboard::*;
use cesium_rs::scene::billboard_collection::*;
use cesium_rs::scene::{
    BlendOption, Camera, CameraFrustum, CameraOptions, FrameResource, FrameState, HorizontalOrigin, SceneMode,
    ScenePrimitive, SceneTransformState, SplitDirection, VerticalOrigin,
};
use serde_json::{json, Value};
use std::{cell::Cell, cell::RefCell, rc::Rc};

const ACTIVE_ATTRIBUTES: f64 = 35721.0;
const ACTIVE_UNIFORMS: f64 = 35718.0;
const ALIASED_POINT_SIZE_RANGE: f64 = 33901.0;
const ALIASED_LINE_WIDTH_RANGE: f64 = 33902.0;
const MAX_VIEWPORT_DIMS: f64 = 3386.0;
const ARRAY_BUFFER: f64 = 34962.0;

#[derive(Clone)]
struct Host {
    next: Rc<Cell<u32>>,
    instancing: bool,
    /// Buffer uploads, in the capture's `[call, target, usage or offset, length, hash]` form.
    uploads: Rc<RefCell<Vec<Value>>>,
}

impl Gl for Host {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([8, 8])
    }
    fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        let number = |i: usize| match args.get(i) {
            Some(GlValue::Number(n)) => Some(*n),
            _ => None,
        };
        match (name, args) {
            ("bufferData", [GlValue::Number(target), GlValue::Bytes(b), GlValue::Number(usage)]) => {
                let hash = if *target == ARRAY_BUFFER { fnv(&canon(b)) } else { fnv(b) };
                self.uploads.borrow_mut().push(json!(["bufferData", target, usage, b.len(), hash]))
            }
            ("bufferSubData", [GlValue::Number(target), GlValue::Number(offset), GlValue::Bytes(b)]) => {
                let hash = if *target == ARRAY_BUFFER { fnv(&canon(b)) } else { fnv(b) };
                self.uploads.borrow_mut().push(json!(["bufferSubData", target, offset, b.len(), hash]))
            }
            _ => {}
        }
        Ok(if name.starts_with("create") {
            self.next.set(self.next.get() + 1);
            GlValue::Object(self.next.get())
        } else {
            match name {
                "getParameter" => match number(0) {
                    Some(ALIASED_POINT_SIZE_RANGE) | Some(ALIASED_LINE_WIDTH_RANGE) | Some(MAX_VIEWPORT_DIMS) => {
                        GlValue::Numbers(vec![1., 4096.])
                    }
                    _ => GlValue::Number(4096.),
                },
                "getExtension" => match args.first() {
                    Some(GlValue::String(s)) if s == "ANGLE_instanced_arrays" && !self.instancing => GlValue::Null,
                    _ => GlValue::Object(0),
                },
                "getProgramParameter" if number(1) == Some(ACTIVE_ATTRIBUTES) => GlValue::Number(0.),
                "getProgramParameter" if number(1) == Some(ACTIVE_UNIFORMS) => GlValue::Number(0.),
                "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                "checkFramebufferStatus" => GlValue::Number(36053.),
                _ => GlValue::Null,
            }
        })
    }
}

fn fnv(bytes: &[u8]) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in bytes {
        h = (h ^ *b as u64).wrapping_mul(0x100000001b3);
    }
    format!("{h:x}")
}

/// Every float32 NaN as 0x7fc00000, as the capture hashes vertex data: the
/// payload V8 leaves in an attribute written from `undefined` is engine-specific.
fn canon(bytes: &[u8]) -> Vec<u8> {
    bytes
        .chunks(4)
        .flat_map(|c| {
            if c.len() == 4 && f32::from_le_bytes([c[0], c[1], c[2], c[3]]).is_nan() {
                0x7fc00000u32.to_le_bytes().to_vec()
            } else {
                c.to_vec()
            }
        })
        .collect()
}

fn floats(bytes: &[u8]) -> Vec<f32> {
    bytes.chunks(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect()
}

fn num(v: &Value) -> f64 {
    match v {
        Value::String(s) if s == "Infinity" => f64::INFINITY,
        Value::String(s) if s == "-Infinity" => f64::NEG_INFINITY,
        Value::Null => f64::NAN,
        _ => v.as_f64().unwrap(),
    }
}
fn nums(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(num).collect()
}
fn c3(v: &Value) -> Cartesian3 {
    let n = nums(v);
    Cartesian3::new(n[0], n[1], n[2])
}
fn c2(v: &Value) -> Cartesian2 {
    let n = nums(v);
    Cartesian2::new(n[0], n[1])
}
fn color(v: &Value) -> Color {
    let n = nums(v);
    Color::new(n[0], n[1], n[2], n[3])
}
fn scalar(v: &Value) -> Option<NearFarScalar> {
    (!v.is_null()).then(|| {
        let n = nums(v);
        NearFarScalar::new(n[0], n[1], n[2], n[3])
    })
}
fn rectangle(v: &Value) -> BoundingRectangle {
    let n = nums(v);
    BoundingRectangle::new(n[0], n[1], n[2], n[3])
}

fn image(v: &Value) -> BillboardImage<Host> {
    if v == "reject" {
        return BillboardImage::Future {
            uri: None,
            future: Box::pin(async { Err(RuntimeError::new("missing image")) }),
        };
    }
    let p = nums(&v["pixels"]);
    let (w, h, seed) = (p[0] as u32, p[1] as u32, p[2] as usize);
    let bytes = (0..(w * h * 4) as usize).map(|k| ((k * 31 + seed * 17) & 255) as u8).collect();
    BillboardImage::pixels(w, h, bytes)
}

fn options(o: &Value) -> (BillboardOptions, Option<BillboardImage<Host>>) {
    let mut b = BillboardOptions::default();
    let mut img = None;
    for (k, v) in o.as_object().unwrap() {
        match k.as_str() {
            "position" => b.position = c3(v),
            "image" => img = Some(image(v)),
            "imageId" => b.image_id = v.as_str().map(String::from),
            "imageSubRegion" => b.image_sub_region = Some(rectangle(v)),
            "pixelOffset" => b.pixel_offset = c2(v),
            "eyeOffset" => b.eye_offset = c3(v),
            "horizontalOrigin" => {
                b.horizontal_origin = HorizontalOrigin::from_value(v.as_i64().unwrap() as i32).unwrap()
            }
            "verticalOrigin" => b.vertical_origin = VerticalOrigin::from_value(v.as_i64().unwrap() as i32).unwrap(),
            "scale" => b.scale = num(v),
            "color" => b.color = color(v),
            "rotation" => b.rotation = num(v),
            "alignedAxis" => b.aligned_axis = c3(v),
            "sizeInMeters" => b.size_in_meters = v.as_bool().unwrap(),
            "width" => b.width = Some(num(v)),
            "height" => b.height = Some(num(v)),
            "id" => b.id = v.as_str().map(String::from),
            "translucencyByDistance" => b.translucency_by_distance = scalar(v),
            "scaleByDistance" => b.scale_by_distance = scalar(v),
            "pixelOffsetScaleByDistance" => b.pixel_offset_scale_by_distance = scalar(v),
            "distanceDisplayCondition" => {
                let n = nums(v);
                b.distance_display_condition = Some(DistanceDisplayCondition::new(n[0], n[1]))
            }
            "disableDepthTestDistance" => b.disable_depth_test_distance = Some(num(v)),
            "splitDirection" => b.split_direction = SplitDirection::from_value(v.as_i64().unwrap() as i32).unwrap(),
            "outlineColor" => b.outline_color = color(v),
            "outlineWidth" => b.outline_width = num(v),
            other => panic!("unknown option {other}"),
        }
    }
    (b, img)
}

fn set(b: &Billboard<Host>, property: &str, v: &Value) {
    match property {
        "position" => b.set_position(c3(v)),
        "color" => b.set_color(color(v)),
        "pixelOffset" => b.set_pixel_offset(c2(v)),
        "eyeOffset" => b.set_eye_offset(c3(v)),
        "rotation" => b.set_rotation(num(v)),
        "scale" => b.set_scale(num(v)),
        "alignedAxis" => b.set_aligned_axis(c3(v)),
        "translucencyByDistance" => b.set_translucency_by_distance(scalar(v)).unwrap(),
        "scaleByDistance" => b.set_scale_by_distance(scalar(v)).unwrap(),
        "pixelOffsetScaleByDistance" => b.set_pixel_offset_scale_by_distance(scalar(v)).unwrap(),
        "distanceDisplayCondition" => {
            let n = nums(v);
            b.set_distance_display_condition(Some(DistanceDisplayCondition::new(n[0], n[1]))).unwrap()
        }
        "disableDepthTestDistance" => b.set_disable_depth_test_distance(Some(num(v))).unwrap(),
        "splitDirection" => b.set_split_direction(SplitDirection::from_value(v.as_i64().unwrap() as i32).unwrap()),
        "horizontalOrigin" => {
            b.set_horizontal_origin(HorizontalOrigin::from_value(v.as_i64().unwrap() as i32).unwrap())
        }
        "verticalOrigin" => b.set_vertical_origin(VerticalOrigin::from_value(v.as_i64().unwrap() as i32).unwrap()),
        "show" => b.set_show(v.as_bool().unwrap()),
        "sizeInMeters" => b.set_size_in_meters(v.as_bool().unwrap()),
        "width" => b.set_width(Some(num(v))),
        "outlineWidth" => b.set_outline_width(num(v)),
        "outlineColor" => b.set_outline_color(color(v)),
        "image" => b.set_image((!v.is_null()).then(|| image(v))),
        other => panic!("unknown property {other}"),
    }
}

fn frame(context: &Context<Host>, camera: &Value) -> FrameState {
    let mut frustum = PerspectiveFrustum::new(std::f64::consts::PI / 3., 4. / 3.);
    (frustum.near, frustum.far) = (1., 1e9);
    let (position, direction, up, right) =
        (c3(&camera["position"]), c3(&camera["direction"]), c3(&camera["up"]), c3(&camera["right"]));
    let view = Matrix4::compute_view(position, direction, up, right);
    let uniform = cesium_rs::renderer::UniformCamera {
        view,
        inverse_view: view.inverse_transformation(),
        position,
        direction,
        right,
        up,
        cartographic: None,
        frustum: UniformFrustum::Perspective(frustum),
    };
    let culling = frustum.compute_culling_volume(position, direction, up);
    let mut frame =
        FrameState::new(UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)), culling, [8, 8]);
    frame.context = Some(FrameResource::new(context.clone()));
    frame.pixel_ratio = 1.;
    frame
}

fn scene_camera(camera: &Value) -> Camera {
    let mut options = CameraOptions::new(8., 8.);
    options.client_width = 800.;
    options.client_height = 600.;
    let mut c = Camera::new(options);
    let mut frustum = PerspectiveFrustum::new(std::f64::consts::PI / 3., 4. / 3.);
    (frustum.near, frustum.far) = (1., 1e9);
    c.frustum = CameraFrustum::Perspective(frustum);
    (c.position, c.direction, c.up, c.right) =
        (c3(&camera["position"]), c3(&camera["direction"]), c3(&camera["up"]), c3(&camera["right"]));
    c.update(SceneMode::Scene3D).unwrap();
    c
}

fn assert_close(actual: f64, expected: &Value, context: &str) {
    let expected = num(expected);
    let tolerance = 1e-9 * expected.abs().max(1.);
    assert!(
        actual == expected || (actual - expected).abs() <= tolerance || (actual.is_nan() && expected.is_nan()),
        "{context}: {actual} != {expected}"
    );
}

fn is_guid(s: &str) -> bool {
    s.len() == 36 && s.chars().filter(|c| *c == '-').count() == 4
}

fn uploads(v: &[Value]) -> Vec<Value> {
    v.iter().map(|u| json!([u[0], num(&u[1]), num(&u[2]), u[3], u[4]])).collect()
}

struct Replay {
    previous: (Option<usize>, Option<usize>),
    camera: Camera,
}

fn check_update(
    collection: &BillboardCollection<Host>,
    billboards: &[Billboard<Host>],
    step: &Value,
    r: &mut Replay,
    context: &str,
) {
    let buffers: Vec<(u32, usize, Vec<u8>)> = collection.vertex_array_facade().map_or_else(Vec::new, |vaf| {
        vaf.buffer_layouts().into_iter().map(|(u, s, b)| (u as u32, s, canon(b))).collect()
    });
    let expected = step["buffers"].as_array().unwrap();
    assert_eq!(buffers.len(), expected.len(), "{context}: buffer count");
    for (i, ((usage, stride, bytes), e)) in buffers.iter().zip(expected).enumerate() {
        assert_eq!(json!(usage), e["usage"], "{context}: buffer {i} usage");
        assert_eq!(json!(stride), e["vertexSizeInBytes"], "{context}: buffer {i} stride");
        assert_eq!(json!(bytes.len()), e["length"], "{context}: buffer {i} length");
        if json!(fnv(bytes)) != e["hash"] {
            let detail = e["bytes"].as_str().map_or(String::new(), |b64| {
                let wanted = base64::engine::general_purpose::STANDARD.decode(b64).unwrap();
                let (a, w) = (floats(bytes), floats(&wanted));
                let stride = stride / 4;
                let rows: Vec<String> = a
                    .chunks(stride)
                    .zip(w.chunks(stride))
                    .enumerate()
                    .filter(|(_, (a, w))| a.iter().zip(*w).any(|(x, y)| x.to_bits() != y.to_bits()))
                    .map(|(v, (a, w))| format!("\n vertex {v}\n  actual   {a:?}\n  expected {w:?}"))
                    .collect();
                rows.join("")
            });
            panic!("{context}: buffer {i} bytes differ{detail}");
        }
    }
    let va_count = collection.vertex_array_facade().and_then(|v| v.vertex_arrays()).map_or(0, |v| v.len());
    assert_eq!(json!(va_count), step["vaCount"], "{context}: vaCount");

    let commands = collection.commands();
    let expected = step["commands"].as_array().unwrap();
    assert_eq!(commands.len(), expected.len(), "{context}: command count");
    for (i, (c, e)) in commands.iter().zip(expected).enumerate() {
        let ctx = format!("{context}: command {i}");
        assert_eq!(json!(c.pass as u32), e["pass"], "{ctx} pass");
        assert_eq!(json!(c.primitive_type as u32), e["primitiveType"], "{ctx} primitiveType");
        assert_eq!(json!(c.vertex_array), e["vaIndex"], "{ctx} vaIndex");
        assert_eq!(json!(c.opaque_program), e["opaqueProgram"], "{ctx} opaqueProgram");
        let rs = &c.render_state;
        assert_eq!(json!(rs.depth_test.enabled), e["renderState"]["depthTest"], "{ctx} depthTest");
        assert_eq!(json!(rs.depth_test.func), e["renderState"]["depthFunc"], "{ctx} depthFunc");
        assert_eq!(json!(rs.depth_mask), e["renderState"]["depthMask"], "{ctx} depthMask");
        assert_eq!(json!(rs.blending.enabled), e["renderState"]["blending"], "{ctx} blending");
        let bv = c.bounding_volume;
        for (k, v) in [bv.center.x, bv.center.y, bv.center.z, bv.radius].iter().enumerate() {
            assert_close(*v, &e["boundingVolume"][k], &format!("{ctx} boundingVolume[{k}]"));
        }
        assert_eq!(c.model_matrix.0.to_vec(), nums(&e["modelMatrix"]), "{ctx} modelMatrix");
        assert_eq!(json!(c.pick_id), e["pickId"], "{ctx} pickId");
        assert_eq!(json!(c.debug_show_bounding_volume), e["debugShowBoundingVolume"], "{ctx} debug");
        assert_eq!(c.count, num(&e["count"]), "{ctx} count");
        assert_eq!(json!(c.instance_count), e["instanceCount"], "{ctx} instanceCount");
        let u = &e["uniforms"];
        assert_eq!(
            vec![
                collection.highlight_color.red,
                collection.highlight_color.green,
                collection.highlight_color.blue,
                collection.highlight_color.alpha
            ],
            nums(&u["highlightColor"]),
            "{ctx} highlightColor"
        );
        assert_close(collection.coarse_depth_test_distance, &u["coarseDepthTestDistance"], &ctx);
        assert_close(collection.three_point_depth_test_distance, &u["threePointDepthTestDistance"], &ctx);
    }

    let program = |p: Option<&BillboardProgram>| {
        p.map_or(Value::Null, |p| json!({"vs": p.vertex_defines, "fs": p.fragment_defines}))
    };
    let (sp, spt) = collection.programs();
    assert_eq!(program(sp), step["sp"], "{context}: sp");
    assert_eq!(program(spt), step["spTranslucent"], "{context}: spTranslucent");
    let (sp, spt) = collection.shader_programs();
    let address = |p: Option<Rc<_>>| p.map(|p: Rc<_>| Rc::as_ptr(&p) as *const () as usize);
    let current = (address(sp), address(spt));
    assert_eq!(json!(current.0 != r.previous.0), step["spChanged"], "{context}: spChanged");
    assert_eq!(json!(current.1 != r.previous.1), step["spTranslucentChanged"], "{context}: spTranslucentChanged");
    r.previous = current;

    let f = &step["flags"];
    let s = collection.shader_flags();
    for (name, v) in [
        ("rotation", s.rotation),
        ("alignedAxis", s.aligned_axis),
        ("scaleByDistance", s.scale_by_distance),
        ("translucencyByDistance", s.translucency_by_distance),
        ("pixelOffsetScaleByDistance", s.pixel_offset_scale_by_distance),
        ("distanceDisplayCondition", s.distance_display_condition),
        ("disableDepthDistance", s.disable_depth_distance),
        ("clampToGround", s.clamp_to_ground),
    ] {
        assert_eq!(json!(v), f[name], "{context}: flag {name}");
    }
    let e = collection.extents();
    assert_eq!(e.max_size, num(&f["maxSize"]), "{context}: maxSize");
    assert_eq!(e.max_eye_offset, num(&f["maxEyeOffset"]), "{context}: maxEyeOffset");
    assert_eq!(e.max_scale, num(&f["maxScale"]), "{context}: maxScale");
    assert_eq!(e.max_pixel_offset, num(&f["maxPixelOffset"]), "{context}: maxPixelOffset");
    assert_eq!(json!(e.all_horizontal_center), f["allHorizontalCenter"], "{context}: allHorizontalCenter");
    assert_eq!(json!(e.all_vertical_center), f["allVerticalCenter"], "{context}: allVerticalCenter");
    assert_eq!(json!(e.all_sized_in_meters), f["allSizedInMeters"], "{context}: allSizedInMeters");
    let usage: Vec<u32> = collection.buffers_usage().iter().map(|u| *u as u32).collect();
    assert_eq!(json!(usage), f["buffersUsage"], "{context}: buffersUsage");
    assert_eq!(json!(collection.properties_changed()), f["propertiesChanged"], "{context}: propertiesChanged");
    assert_eq!(json!(collection.billboards_to_update()), f["toUpdateIndex"], "{context}: toUpdateIndex");
    assert_eq!(json!(collection.ready()), f["ready"], "{context}: ready");

    if let Some(expected) = step["screen"].as_array() {
        let projection = GeographicProjection::default();
        let state = SceneTransformState {
            mode: SceneMode::Scene3D,
            morph_time: 1.,
            map_projection: &projection,
            client_dimensions: Cartesian2::new(800., 600.),
            drawing_buffer_dimensions: Cartesian2::new(8., 8.),
        };
        for (i, (b, e)) in billboards.iter().zip(expected).enumerate() {
            let actual = collection.compute_screen_space_position(b, &state, &mut r.camera);
            if e.is_null() {
                assert!(actual.is_err(), "{context}: screen {i}");
                continue;
            }
            let w = actual.unwrap().unwrap();
            assert_close(w.x, &e[0], &format!("{context}: screen {i} x"));
            assert_close(w.y, &e[1], &format!("{context}: screen {i} y"));
        }
    }
}

fn check_after_render(
    collection: &BillboardCollection<Host>,
    billboards: &[Billboard<Host>],
    step: &Value,
    guid: &mut String,
    context: &str,
) {
    let atlas = collection.texture_atlas();
    let atlas = atlas.borrow();
    let a = &step["atlas"];
    assert_eq!(json!(atlas.texture().map(|t| [t.width(), t.height()])), a["texture"], "{context}: atlas texture");
    assert_eq!(json!(atlas.guid() != guid), a["guidChanged"], "{context}: atlas guid");
    *guid = atlas.guid().to_string();
    let rectangles: Vec<Value> =
        atlas.rectangles().iter().map(|r| r.map_or(Value::Null, |r| json!([r.x, r.y, r.width, r.height]))).collect();
    let expected: Vec<Value> = a["rectangles"]
        .as_array()
        .unwrap()
        .iter()
        .map(|r| if r.is_null() { Value::Null } else { json!(nums(r)) })
        .collect();
    let mut rectangles: Vec<Value> =
        rectangles.iter().map(|r| if r.is_null() { Value::Null } else { json!(nums(r)) }).collect();
    // Cesium's `_rectangles` is a sparse array: an index whose image never
    // packed (a rejected load) has no trailing entry.
    while rectangles.len() > expected.len() && rectangles.last() == Some(&Value::Null) {
        rectangles.pop();
    }
    assert_eq!(rectangles, expected, "{context}: atlas rectangles");
    drop(atlas);
    for (i, (b, e)) in billboards.iter().zip(step["billboards"].as_array().unwrap()).enumerate() {
        let ctx = format!("{context}: billboard {i}");
        assert_eq!(json!(b.index()), e["index"], "{ctx} index");
        assert_eq!(json!(b.is_dirty()), e["dirty"], "{ctx} dirty");
        assert_eq!(json!(b.texture_dirty()), e["textureDirty"], "{ctx} textureDirty");
        assert_eq!(json!(b.load_state().value()), e["loadState"], "{ctx} loadState");
        assert_eq!(json!(b.ready()), e["ready"], "{ctx} ready");
        match (b.image(), e["image"].as_str()) {
            (Some(a), Some(w)) if is_guid(w) => assert!(is_guid(&a), "{ctx} image {a} is not a GUID"),
            (a, w) => assert_eq!(a.as_deref(), w, "{ctx} image"),
        }
        assert_eq!(json!(b.image_index()), e["imageIndex"], "{ctx} imageIndex");
        assert_eq!(
            b.width().map_or(Value::Null, |w| json!(w)),
            if e["width"].is_null() { Value::Null } else { json!(num(&e["width"])) },
            "{ctx} width"
        );
        assert_eq!(
            b.height().map_or(Value::Null, |h| json!(h)),
            if e["height"].is_null() { Value::Null } else { json!(num(&e["height"])) },
            "{ctx} height"
        );
        assert_eq!(json!(b.load_error().is_some()), e["loadError"], "{ctx} loadError");
        let p = b.actual_position();
        for (k, v) in [p.x, p.y, p.z].iter().enumerate() {
            assert_close(*v, &e["actual"][k], &format!("{ctx} actual[{k}]"));
        }
    }
}

#[test]
fn updates_match_cesium_vertex_bytes_commands_atlas_and_images() {
    let fixture: Value = serde_json::from_str(include_str!("data/scene-billboard-collection.json")).unwrap();
    let capture = &fixture["capture"];
    let mut updates = 0;
    for (name, script) in fixture["scenarios"].as_object().unwrap() {
        let batched = name.ends_with("Batched");
        let host = Host { next: Rc::default(), instancing: !batched, uploads: Rc::default() };
        let context = if batched { Context::new_webgl1(host.clone()) } else { Context::new_webgl2(host.clone()) };
        let scenario = &capture["scenarios"][name];
        let mut frame = frame(&context, &scenario["camera"]);
        let mut collection = BillboardCollection::<Host>::default();
        let mut guid = collection.texture_atlas().borrow().guid().to_string();
        let mut billboards: Vec<Billboard<Host>> = Vec::new();
        let mut steps = scenario["steps"].as_array().unwrap().iter();
        let mut replay = Replay { previous: (None, None), camera: scene_camera(&scenario["camera"]) };
        for (op_index, op) in script.as_array().unwrap().iter().enumerate() {
            let ctx = format!("{name} op {op_index} {op}");
            host.uploads.borrow_mut().clear();
            match op[0].as_str().unwrap() {
                "add" => {
                    let (o, img) = options(&op[1]);
                    billboards.push(collection.add(o, img).unwrap());
                }
                "set" => set(&billboards[op[1].as_u64().unwrap() as usize], op[2].as_str().unwrap(), &op[3]),
                "call" => {
                    let b = &billboards[op[1].as_u64().unwrap() as usize];
                    let id = op[3].as_str().unwrap();
                    match op[2].as_str().unwrap() {
                        "setImage" => b.set_image_with_id(id, image(&op[4])),
                        "setImageSubRegion" => b.set_image_sub_region(id, rectangle(&op[4])).unwrap(),
                        other => panic!("unknown call {other}"),
                    }
                }
                "remove" => {
                    let removed = collection.remove(&billboards[op[1].as_u64().unwrap() as usize]).unwrap();
                    assert_eq!(json!(removed), steps.next().unwrap()["removed"], "{ctx}");
                }
                "removeAll" => collection.remove_all().unwrap(),
                "collection" => match op[1].as_str().unwrap() {
                    "blendOption" => {
                        collection.blend_option = BlendOption::from_value(op[2].as_i64().unwrap() as i32).unwrap()
                    }
                    "modelMatrix" => collection.model_matrix = Matrix4(nums(&op[2]).try_into().unwrap()),
                    "show" => collection.show = op[2].as_bool().unwrap(),
                    "debugShowBoundingVolume" => collection.debug_show_bounding_volume = op[2].as_bool().unwrap(),
                    "_sdf" => collection.set_sdf(op[2].as_bool().unwrap()),
                    other => panic!("unknown collection property {other}"),
                },
                "update" => {
                    let o = &op[1];
                    let mode = SceneMode::from_value(o["mode"].as_i64().unwrap() as i32).unwrap();
                    frame.mode = mode;
                    frame.morph_time =
                        o["morphTime"].as_f64().unwrap_or(if mode == SceneMode::Scene3D { 1. } else { 0. });
                    frame.passes.render = o["render"].as_bool().unwrap_or(true);
                    frame.passes.pick = o["pick"].as_bool().unwrap_or(false);
                    frame.minimum_disable_depth_test_distance =
                        Some(o["minimumDisableDepthTestDistance"].as_f64().unwrap_or(0.));
                    frame.command_list.clear();
                    collection.update(&mut frame).unwrap();
                    assert_eq!(frame.command_list.len(), collection.commands().len(), "{ctx}: queued");
                    let step = steps.next().unwrap();
                    assert_eq!(step["op"], *op);
                    check_update(&collection, &billboards, step, &mut replay, &ctx);
                    let made = host.uploads.borrow().clone();
                    assert_eq!(uploads(&made), uploads(step["uploads"].as_array().unwrap()), "{ctx}: uploads");
                    host.uploads.borrow_mut().clear();
                    for callback in std::mem::take(&mut frame.after_render) {
                        callback().unwrap();
                    }
                    let made = host.uploads.borrow().clone();
                    assert_eq!(
                        uploads(&made),
                        uploads(step["afterRenderUploads"].as_array().unwrap()),
                        "{ctx}: afterRender uploads"
                    );
                    check_after_render(&collection, &billboards, step, &mut guid, &ctx);
                    updates += 1;
                }
                other => panic!("unknown op {other}"),
            }
        }
        assert!(steps.next().is_none(), "{name}: unreplayed steps");
        collection.destroy().unwrap();
        assert!(billboards.iter().all(|b| !b.is_attached()));
    }
    assert_eq!(updates, 85);
}
